import fs from 'node:fs';import vm from 'node:vm';import assert from 'node:assert/strict';
const read=p=>fs.readFileSync(new URL('../'+p,import.meta.url),'utf8'),win={},ctx=vm.createContext({window:win});
for(const m of read('students/index.html').matchAll(/src="([^"?]+\.js)/g)){if(m[1]==='app.js')break;vm.runInContext(read('students/'+m[1]),ctx)}
const F=win.MT_FORMULAS,S=win.MT_STUDY,byId=new Map(F.map(f=>[f.id,f]));let checks=0;const ok=(v,m)=>{assert.ok(v,m);checks++};
ok(F.length===529,'499 baseline entries plus four physics and sixteen mechanics and four machine-element and six chemistry families');
const baseline=JSON.parse(read('tests/fixtures/students-baseline-499-ids.json'));ok(baseline.every(id=>byId.has(id)),'every baseline ID preserved');
for(const f of F){const vars=S.details[f.id]?.symbols;ok(vars?.length>0&&vars.every(v=>v.symbol&&v.meaning&&v.unit),'local variable meanings and units for '+f.id)}
const unit=(id,glyph)=>S.details[id].symbols.find(v=>v.symbol===glyph)?.unit;
ok(unit('volumetric-flow','Q')==='m³/s','Q as flow');ok(unit('capacitor-charge','Q')==='C','Q as electric charge');ok(unit('three-phase-reactive-power','Q')==='var','Q as reactive power');ok(unit('power','P')==='W','P as mechanical power');ok(unit('student-v2-simple-interest','P')==='currency','P as monetary principal');ok(unit('rate-of-turn','Δt')==='min','degree/minute rate has minute time base');ok(unit('endurance-by-volume','daily volume consumption')==='m³/day','volume endurance rate uses days');ok(unit('battery-energy-approx','C')==='Ah','battery C is charge capacity, not capacitance');ok(unit('capacitor-energy','C')==='F','capacitor C is capacitance');ok(unit('righting-moment','Mmass')==='t·m','mass moment cannot masquerade as Nm');ok(byId.get('loll-heel-small-angle-relation').note.includes('not a formula for angle of loll'),'positive-GM equilibrium separated from loll');ok(byId.get('ext-hog-sag-first-correction-three-drafts').note.includes('ADDED to the corrected MIDSHIP'),'draft correction states where it is added');
const rows=S.equationAudit;ok(rows.length===262,'262 separately identified mathematical source expressions');ok(new Set(rows.map(r=>r.id)).size===262,'source-expression identifiers unique');ok(new Set(rows.map(r=>r.page)).size===16,'all sixteen mathematics pages represented');
for(const r of rows)ok(byId.has(r.formulaId)&&r.symbols.length&&r.conditions&&r.sourceReadStatus==='VISUALLY_READ','each captured expression mapped with assumptions: '+r.id);
ok(rows.filter(r=>r.symbolicStatus!=='PENDING').length===65,'symbolic checks counted separately from source readings');ok(rows.filter(r=>r.symbolicStatus==='PENDING').length===197,'unvalidated expressions remain explicitly pending');ok(rows.filter(r=>r.sourceIssue.includes('tangent')).length>=1,'source tangent error has explicit correction record');
ok(read('students/app.js').includes('f.related||[]'),'source variants searchable and renderable');ok(read('sw.js').includes("'./students/symbol-definitions-20261020.js'")&&read('sw.js').includes("'./students/math-equation-audit-20261020.js'"),'new data assets cached');
console.log(JSON.stringify({status:'PASS',checks,formulas:F.length,withSymbolTables:F.filter(f=>S.details[f.id]?.symbols?.length).length,contextualSymbolEntries:win.MT_SYMBOLS.entries.length,capturedExpressions:rows.length,symbolicIdentities:65,remainingNumericalReview:197,scope:'metadata and source-register integrity; full textbook verification remains incomplete'}));
